import { useState, useMemo } from 'react';
import { useLocation } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Search, BookOpen, Printer, X } from 'lucide-react';
import { glossaryTerms } from '../data/content';
import { Input } from '../components/ui/input';
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '../components/ui/accordion';

const GlossairePage = () => {
  const location = useLocation();
  const isEnglish = location.pathname.startsWith('/en');
  const [searchQuery, setSearchQuery] = useState('');

  const filteredTerms = useMemo(() => {
    if (!searchQuery.trim()) return glossaryTerms;
    const query = searchQuery.toLowerCase();
    return glossaryTerms.filter(term =>
      term.term.toLowerCase().includes(query) ||
      term.definition.toLowerCase().includes(query) ||
      (term.english && term.english.toLowerCase().includes(query))
    );
  }, [searchQuery]);

  const handlePrint = () => {
    window.print();
  };

  return (
    <div className="min-h-screen pt-20 md:pt-24" data-testid="glossaire-page">
      {/* Header */}
      <section className="py-12 md:py-16 border-b border-[#E6E4DD]">
        <div className="container-full">
          <span className="overline text-[#B65F4A] mb-4 block">{isEnglish ? 'Essential Vocabulary' : 'Vocabulaire essentiel'}</span>
          <h1 className="mb-4">{isEnglish ? 'Glossary' : 'Glossaire'}</h1>
          <p className="text-lg text-[#5C5856] max-w-2xl">
            {isEnglish
              ? 'Definitions of key terms in Indigenous history in Quebec and Canada to support revision and exam preparation.'
              : "Définitions des termes clés de l'histoire autochtone du Québec et du Canada pour préparer vos examens."}
          </p>
          {isEnglish && (
            <p className="mt-4 max-w-2xl text-sm text-[#5C5856] bg-[#FAFAF7] border border-[#E6E4DD] rounded-sm p-4">
              English terminology is available where possible. Most full definitions still follow the French source content.
            </p>
          )}
        </div>
      </section>

      {/* Search and Actions */}
      <section className="py-6 border-b border-[#E6E4DD] bg-white sticky top-16 md:top-20 z-40 no-print">
        <div className="container-full">
          <div className="flex flex-col sm:flex-row gap-4 items-stretch sm:items-center justify-between">
            <div className="relative flex-1 max-w-md">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-[#5C5856]" />
              <Input
                type="text"
                placeholder={isEnglish ? 'Search for a term...' : 'Rechercher un terme...'}
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-10 border-[#E6E4DD] rounded-sm"
                data-testid="glossary-search"
              />
              {searchQuery && (
                <button
                  onClick={() => setSearchQuery('')}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-[#5C5856] hover:text-[#2D2926]"
                >
                  <X className="w-4 h-4" />
                </button>
              )}
            </div>
            <button
              onClick={handlePrint}
              className="btn-secondary flex items-center justify-center gap-2"
              data-testid="print-glossary-btn"
            >
              <Printer className="w-4 h-4" />
              {isEnglish ? 'Print' : 'Imprimer'}
            </button>
          </div>
        </div>
      </section>

      {/* Glossary Content */}
      <section className="section-spacing">
        <div className="container-narrow">
          {filteredTerms.length === 0 ? (
            <div className="text-center py-12">
              <BookOpen className="w-12 h-12 mx-auto mb-4 text-[#E6E4DD]" />
              <p className="text-[#5C5856]">{isEnglish ? `No term found for "${searchQuery}"` : `Aucun terme trouvé pour « ${searchQuery} »`}</p>
              <button
                onClick={() => setSearchQuery('')}
                className="mt-4 text-[#B65F4A] font-semibold hover:underline"
              >
                {isEnglish ? 'Clear search' : 'Effacer la recherche'}
              </button>
            </div>
          ) : (
            <>
              <p className="text-sm text-[#5C5856] mb-6">
                {isEnglish
                  ? `${filteredTerms.length} term${filteredTerms.length > 1 ? 's' : ''}${searchQuery ? ` for "${searchQuery}"` : ''}`
                  : `${filteredTerms.length} terme${filteredTerms.length > 1 ? 's' : ''}${searchQuery ? ` pour « ${searchQuery} »` : ''}`}
              </p>

              <Accordion type="single" collapsible className="space-y-2" data-testid="glossary-accordion">
                {filteredTerms.map((item, index) => (
                  <motion.div
                    key={item.id}
                    initial={{ opacity: 0, y: 10 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.3, delay: index * 0.03 }}
                  >
                    <AccordionItem 
                      value={`item-${item.id}`} 
                      className="border border-[#E6E4DD] rounded-sm bg-white"
                      data-testid={`glossary-item-${item.id}`}
                    >
                      <AccordionTrigger className="px-6 py-4 hover:no-underline hover:bg-[#FAFAF7]">
                        <div className="flex items-center gap-4 text-left">
                          <span className="font-['Playfair_Display'] font-semibold text-[#2D2926]">
                            {isEnglish && item.english ? item.english : item.term}
                          </span>
                          {item.english && (
                            <span className="text-xs text-[#5C5856] italic">
                              ({isEnglish ? item.term : item.english})
                            </span>
                          )}
                        </div>
                      </AccordionTrigger>
                      <AccordionContent className="px-6 pb-4">
                        <p className="text-[#5C5856] leading-relaxed">
                          {item.definition}
                        </p>
                      </AccordionContent>
                    </AccordionItem>
                  </motion.div>
                ))}
              </Accordion>
            </>
          )}

          {/* Print Version - Grid */}
          <div className="hidden print:block mt-8">
            <h2 className="text-xl font-semibold mb-4">{isEnglish ? 'Vocabulary Grid' : 'Grille de vocabulaire'}</h2>
            <table className="w-full border-collapse text-sm">
              <thead>
                <tr>
                  <th className="border p-2 text-left bg-gray-100">{isEnglish ? 'Term' : 'Terme'}</th>
                  <th className="border p-2 text-left bg-gray-100">{isEnglish ? 'Definition' : 'Définition'}</th>
                </tr>
              </thead>
              <tbody>
                {glossaryTerms.map((item) => (
                  <tr key={item.id}>
                    <td className="border p-2 font-semibold">{isEnglish && item.english ? item.english : item.term}</td>
                    <td className="border p-2">{item.definition}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </section>

      {/* Quick Reference Grid */}
      <section className="section-spacing bg-white no-print">
        <div className="container-full">
          <h2 className="text-2xl mb-8">{isEnglish ? 'Quick Reference Grid' : 'Grille de référence rapide'}</h2>
          <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4">
            {glossaryTerms.slice(0, 9).map((item) => (
              <div 
                key={item.id}
                className="p-4 bg-[#FAFAF7] border border-[#E6E4DD] rounded-sm"
                data-testid={`quick-ref-${item.id}`}
              >
                <h4 className="font-['Playfair_Display'] font-semibold text-[#2D2926] mb-1">
                  {isEnglish && item.english ? item.english : item.term}
                </h4>
                <p className="text-sm text-[#5C5856] line-clamp-2">
                  {item.definition}
                </p>
              </div>
            ))}
          </div>
        </div>
      </section>
    </div>
  );
};

export default GlossairePage;
