import { BookOpen, Info, Lightbulb, AlertCircle } from 'lucide-react';

const calloutTypes = {
  remember: {
    icon: BookOpen,
    title: 'À retenir',
    className: 'callout-remember',
    iconColor: 'text-[#4B6858]',
  },
  context: {
    icon: Info,
    title: 'En contexte',
    className: 'callout-context',
    iconColor: 'text-[#D49A36]',
  },
  explore: {
    icon: Lightbulb,
    title: 'Pour aller plus loin',
    className: 'callout-explore',
    iconColor: 'text-[#B65F4A]',
  },
  important: {
    icon: AlertCircle,
    title: 'Mot important',
    className: 'callout-important',
    iconColor: 'text-[#B65F4A]',
  },
};

const englishTitles = {
  remember: 'Remember',
  context: 'In Context',
  explore: 'Go Further',
  important: 'Key Term',
};

export const Callout = ({ type = 'remember', title, children, className = '', locale = 'fr' }) => {
  const config = calloutTypes[type] || calloutTypes.remember;
  const Icon = config.icon;
  const displayTitle = title || (locale === 'en' ? englishTitles[type] || config.title : config.title);

  return (
    <div 
      className={`callout ${config.className} ${className}`}
      data-testid={`callout-${type}`}
    >
      <div className="flex items-start gap-3">
        <Icon className={`w-5 h-5 mt-0.5 flex-shrink-0 ${config.iconColor}`} />
        <div>
          <h4 className="font-semibold text-[#2D2926] mb-1 text-sm uppercase tracking-wide">
            {displayTitle}
          </h4>
          <div className="text-[#5C5856] text-sm leading-relaxed">
            {children}
          </div>
        </div>
      </div>
    </div>
  );
};

export const KeyTermBox = ({ term, definition, english }) => {
  return (
    <div 
      className="p-4 bg-white border border-[#E6E4DD] rounded-sm"
      data-testid={`key-term-${term.toLowerCase().replace(/\s+/g, '-')}`}
    >
      <div className="flex items-start justify-between gap-4">
        <div>
          <h4 className="font-['Playfair_Display'] font-semibold text-[#2D2926]">
            {term}
          </h4>
          {english && (
            <span className="text-xs text-[#5C5856] italic">
              ({english})
            </span>
          )}
        </div>
      </div>
      <p className="mt-2 text-sm text-[#5C5856] leading-relaxed">
        {definition}
      </p>
    </div>
  );
};

export const QuoteBox = ({ text, author, context }) => {
  return (
    <blockquote 
      className="my-6 pl-6 border-l-4 border-[#B65F4A]"
      data-testid="quote-box"
    >
      <p className="font-['Playfair_Display'] text-lg italic text-[#2D2926] mb-2">
        « {text} »
      </p>
      {(author || context) && (
        <footer className="text-sm text-[#5C5856]">
          {author && <span className="font-semibold">{author}</span>}
          {author && context && ' — '}
          {context && <span className="italic">{context}</span>}
        </footer>
      )}
    </blockquote>
  );
};
