import { useState, useMemo } from 'react';
import { useLocation } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { CheckCircle, XCircle, RefreshCw, Trophy, ChevronRight, Filter } from 'lucide-react';
import { quizQuestions } from '../data/content';
import { Button } from '../components/ui/button';
import { Progress } from '../components/ui/progress';

const QuizPage = () => {
  const location = useLocation();
  const isEnglish = location.pathname.startsWith('/en');
  const [selectedDifficulty, setSelectedDifficulty] = useState('all');
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState(null);
  const [showResult, setShowResult] = useState(false);
  const [score, setScore] = useState(0);
  const [quizComplete, setQuizComplete] = useState(false);
  const [answeredQuestions, setAnsweredQuestions] = useState([]);

  const filteredQuestions = useMemo(() => {
    if (selectedDifficulty === 'all') return quizQuestions.filter(q => q.type === 'multiple-choice' || q.type === 'true-false');
    return quizQuestions.filter(q => 
      (q.type === 'multiple-choice' || q.type === 'true-false') && 
      q.difficulty === selectedDifficulty
    );
  }, [selectedDifficulty]);

  const currentQuestion = filteredQuestions[currentQuestionIndex];
  const progress = filteredQuestions.length > 0 ? ((currentQuestionIndex + 1) / filteredQuestions.length) * 100 : 0;

  const handleAnswerSelect = (answerIndex) => {
    if (showResult) return;
    setSelectedAnswer(answerIndex);
  };

  const handleSubmitAnswer = () => {
    if (selectedAnswer === null) return;
    
    const isCorrect = currentQuestion.type === 'true-false' 
      ? selectedAnswer === (currentQuestion.correctAnswer ? 0 : 1)
      : selectedAnswer === currentQuestion.correctAnswer;
    
    if (isCorrect) {
      setScore(score + 1);
    }
    
    setAnsweredQuestions([...answeredQuestions, {
      questionId: currentQuestion.id,
      correct: isCorrect
    }]);
    
    setShowResult(true);
  };

  const handleNextQuestion = () => {
    if (currentQuestionIndex < filteredQuestions.length - 1) {
      setCurrentQuestionIndex(currentQuestionIndex + 1);
      setSelectedAnswer(null);
      setShowResult(false);
    } else {
      setQuizComplete(true);
    }
  };

  const handleRestart = () => {
    setCurrentQuestionIndex(0);
    setSelectedAnswer(null);
    setShowResult(false);
    setScore(0);
    setQuizComplete(false);
    setAnsweredQuestions([]);
  };

  const getAnswerOptions = () => {
    if (currentQuestion.type === 'true-false') {
      return isEnglish ? ['True', 'False'] : ['Vrai', 'Faux'];
    }
    return currentQuestion.options;
  };

  const difficultyLabels = {
    all: isEnglish ? 'All' : 'Tous',
    facile: isEnglish ? 'Easy' : 'Facile',
    intermédiaire: isEnglish ? 'Intermediate' : 'Intermédiaire',
    avancé: isEnglish ? 'Advanced' : 'Avancé',
  };

  const isAnswerCorrect = (index) => {
    if (currentQuestion.type === 'true-false') {
      return index === (currentQuestion.correctAnswer ? 0 : 1);
    }
    return index === currentQuestion.correctAnswer;
  };

  return (
    <div className="min-h-screen pt-20 md:pt-24" data-testid="quiz-page">
      {/* Header */}
      <section className="py-12 md:py-16 border-b border-[#E6E4DD]">
        <div className="container-full">
          <span className="overline text-[#B65F4A] mb-4 block">{isEnglish ? 'Test your knowledge' : 'Testez vos connaissances'}</span>
          <h1 className="mb-4">{isEnglish ? 'Review Quiz' : 'Quiz de révision'}</h1>
          <p className="text-lg text-[#5C5856] max-w-2xl">
            {isEnglish
              ? 'Check your understanding of Indigenous history with multiple-choice and true-or-false questions.'
              : "Vérifiez votre compréhension de l'histoire autochtone avec ces questions à choix multiples et vrai/faux."}
          </p>
          {isEnglish && (
            <p className="mt-4 max-w-2xl text-sm text-[#5C5856] bg-[#FAFAF7] border border-[#E6E4DD] rounded-sm p-4">
              The quiz interface is now available in English. Some question text and explanations remain in French while translation continues.
            </p>
          )}
        </div>
      </section>

      {/* Difficulty Filter */}
      <section className="py-6 border-b border-[#E6E4DD] bg-white">
        <div className="container-full">
          <div className="flex items-center gap-4">
            <Filter className="w-5 h-5 text-[#5C5856]" />
            <span className="text-sm text-[#5C5856]">{isEnglish ? 'Difficulty:' : 'Difficulté :'}</span>
            <div className="flex gap-2">
              {['all', 'facile', 'intermédiaire', 'avancé'].map((diff) => (
                <button
                  key={diff}
                  onClick={() => {
                    setSelectedDifficulty(diff);
                    handleRestart();
                  }}
                  className={`filter-btn ${selectedDifficulty === diff ? 'active' : ''}`}
                  data-testid={`difficulty-${diff}`}
                >
                  {difficultyLabels[diff]}
                </button>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* Quiz Content */}
      <section className="section-spacing">
        <div className="container-narrow">
          {filteredQuestions.length === 0 ? (
            <div className="text-center py-12">
              <p className="text-[#5C5856]">{isEnglish ? 'No questions are available for this difficulty level.' : 'Aucune question disponible pour ce niveau de difficulté.'}</p>
              <button
                onClick={() => setSelectedDifficulty('all')}
                className="mt-4 text-[#B65F4A] font-semibold hover:underline"
              >
                {isEnglish ? 'Show all questions' : 'Afficher toutes les questions'}
              </button>
            </div>
          ) : quizComplete ? (
            <QuizResults 
              score={score} 
              total={filteredQuestions.length} 
              onRestart={handleRestart}
              answeredQuestions={answeredQuestions}
              questions={filteredQuestions}
              isEnglish={isEnglish}
            />
          ) : (
            <div className="max-w-2xl mx-auto">
              {/* Progress */}
              <div className="mb-8">
                <div className="flex justify-between text-sm text-[#5C5856] mb-2">
                  <span>{isEnglish ? `Question ${currentQuestionIndex + 1} of ${filteredQuestions.length}` : `Question ${currentQuestionIndex + 1} sur ${filteredQuestions.length}`}</span>
                  <span>Score: {score}/{currentQuestionIndex + (showResult ? 1 : 0)}</span>
                </div>
                <Progress value={progress} className="h-2" />
              </div>

              {/* Question Card */}
              <motion.div
                key={currentQuestion.id}
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                className="card-museum p-8"
                data-testid="quiz-question-card"
              >
                <div className={`activity-difficulty difficulty-${currentQuestion.difficulty} mb-4`}>
                  {currentQuestion.difficulty}
                </div>

                <h2 className="text-xl mb-6">{currentQuestion.question}</h2>

                <div className="space-y-3 mb-6">
                  {getAnswerOptions().map((option, index) => {
                    let optionClass = 'quiz-option';
                    if (showResult) {
                      if (isAnswerCorrect(index)) {
                        optionClass += ' correct';
                      } else if (selectedAnswer === index) {
                        optionClass += ' incorrect';
                      }
                    } else if (selectedAnswer === index) {
                      optionClass += ' selected';
                    }

                    return (
                      <button
                        key={index}
                        onClick={() => handleAnswerSelect(index)}
                        className={`${optionClass} w-full text-left flex items-center justify-between`}
                        disabled={showResult}
                        data-testid={`quiz-option-${index}`}
                      >
                        <span>{option}</span>
                        {showResult && isAnswerCorrect(index) && (
                          <CheckCircle className="w-5 h-5 text-[#4B6858]" />
                        )}
                        {showResult && selectedAnswer === index && !isAnswerCorrect(index) && (
                          <XCircle className="w-5 h-5 text-red-500" />
                        )}
                      </button>
                    );
                  })}
                </div>

                {/* Result Explanation */}
                <AnimatePresence>
                  {showResult && (
                    <motion.div
                      initial={{ opacity: 0, height: 0 }}
                      animate={{ opacity: 1, height: 'auto' }}
                      exit={{ opacity: 0, height: 0 }}
                      className="mb-6 p-4 bg-[#FAFAF7] border border-[#E6E4DD] rounded-sm"
                    >
                      <p className="text-sm text-[#5C5856]">
                        <strong>{isEnglish ? 'Explanation:' : 'Explication :'}</strong> {currentQuestion.explanation}
                      </p>
                    </motion.div>
                  )}
                </AnimatePresence>

                {/* Actions */}
                <div className="flex justify-end gap-4">
                  {!showResult ? (
                    <Button
                      onClick={handleSubmitAnswer}
                      disabled={selectedAnswer === null}
                      className="bg-[#B65F4A] hover:bg-[#9D5240] rounded-sm"
                      data-testid="submit-answer-btn"
                    >
                      {isEnglish ? 'Check answer' : 'Vérifier la réponse'}
                    </Button>
                  ) : (
                    <Button
                      onClick={handleNextQuestion}
                      className="bg-[#B65F4A] hover:bg-[#9D5240] rounded-sm"
                      data-testid="next-question-btn"
                    >
                      {currentQuestionIndex < filteredQuestions.length - 1
                        ? (isEnglish ? 'Next question' : 'Question suivante')
                        : (isEnglish ? 'View results' : 'Voir les résultats')}
                      <ChevronRight className="w-4 h-4 ml-2" />
                    </Button>
                  )}
                </div>
              </motion.div>
            </div>
          )}
        </div>
      </section>
    </div>
  );
};

const QuizResults = ({ score, total, onRestart, answeredQuestions, questions, isEnglish }) => {
  const percentage = Math.round((score / total) * 100);
  
  const getMessage = () => {
    if (isEnglish) {
      if (percentage >= 90) return 'Excellent. You know this material very well.';
      if (percentage >= 70) return 'Very good. Keep going.';
      if (percentage >= 50) return 'Not bad. A bit more review will help.';
      return 'Keep studying. You can improve quickly.';
    }
    if (percentage >= 90) return "Excellent! Tu maîtrises bien le sujet!";
    if (percentage >= 70) return "Très bien! Continue comme ça!";
    if (percentage >= 50) return "Pas mal! Révise encore un peu.";
    return "Continue à étudier, tu peux t'améliorer!";
  };

  return (
    <motion.div
      initial={{ opacity: 0, scale: 0.95 }}
      animate={{ opacity: 1, scale: 1 }}
      className="max-w-lg mx-auto text-center"
      data-testid="quiz-results"
    >
      <div className="card-museum p-8">
        <Trophy className="w-16 h-16 mx-auto mb-4 text-[#D49A36]" />
        <h2 className="text-2xl mb-2">{isEnglish ? 'Quiz complete' : 'Quiz terminé!'}</h2>
        <p className="text-[#5C5856] mb-6">{getMessage()}</p>

        <div className="text-5xl font-bold text-[#B65F4A] mb-2">
          {score}/{total}
        </div>
        <p className="text-[#5C5856] mb-8">{isEnglish ? `${percentage}% correct answers` : `${percentage}% de bonnes réponses`}</p>

        <div className="flex justify-center gap-4">
          <Button
            onClick={onRestart}
            className="bg-[#B65F4A] hover:bg-[#9D5240] rounded-sm"
            data-testid="restart-quiz-btn"
          >
            <RefreshCw className="w-4 h-4 mr-2" />
            {isEnglish ? 'Restart' : 'Recommencer'}
          </Button>
        </div>
      </div>

      {/* Review */}
      <div className="mt-8 text-left">
        <h3 className="text-lg font-semibold mb-4">{isEnglish ? 'Answer review' : 'Révision des réponses'}</h3>
        <div className="space-y-3">
          {questions.map((question, idx) => {
            const answer = answeredQuestions.find(a => a.questionId === question.id);
            return (
              <div 
                key={question.id}
                className={`p-4 border rounded-sm ${answer?.correct ? 'border-[#4B6858] bg-[#4B6858]/5' : 'border-red-300 bg-red-50'}`}
              >
                <div className="flex items-start gap-3">
                  {answer?.correct ? (
                    <CheckCircle className="w-5 h-5 text-[#4B6858] flex-shrink-0 mt-0.5" />
                  ) : (
                    <XCircle className="w-5 h-5 text-red-500 flex-shrink-0 mt-0.5" />
                  )}
                  <div>
                    <p className="text-sm font-medium">{question.question}</p>
                    <p className="text-xs text-[#5C5856] mt-1">{question.explanation}</p>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </motion.div>
  );
};

export default QuizPage;
