const exactPathMap = {
  '/': '/en',
  '/en': '/',
  '/max-gros-louis': '/en/max-gros-louis',
  '/en/max-gros-louis': '/max-gros-louis',
  '/themes': '/en/themes',
  '/en/themes': '/themes',
  '/chronologie': '/en/timeline',
  '/en/timeline': '/chronologie',
  '/quiz': '/en/quiz',
  '/en/quiz': '/quiz',
  '/glossaire': '/en/glossary',
  '/en/glossary': '/glossaire',
  '/activites': '/en/activities',
  '/en/activities': '/activites',
  '/enseignants': '/en/teachers',
  '/en/teachers': '/enseignants',
};

export function getLanguageSwitchPath(pathname) {
  const [path, search = ''] = pathname.split('?');
  const targetPath = exactPathMap[path] || (path.startsWith('/en') ? '/' : '/en');
  return search ? `${targetPath}?${search}` : targetPath;
}
