import { useState, useEffect } from 'react';
import { useLocation, useSearchParams } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { Scale, FileText, Landmark, Users, AlertTriangle, Shield, ChevronRight, ArrowRight } from 'lucide-react';
import { historicalThemes } from '../data/content';
import { LevelToggle, LevelContent, LevelBadge } from '../components/shared/LevelToggle';
import { Callout } from '../components/shared/Callout';

const iconMap = {
  Scale: Scale,
  FileText: FileText,
  Landmark: Landmark,
  Users: Users,
  AlertTriangle: AlertTriangle,
  Shield: Shield,
};

const ThemesPage = () => {
  const location = useLocation();
  const isEnglish = location.pathname.startsWith('/en');
  const [searchParams] = useSearchParams();
  const initialLevel = parseInt(searchParams.get('level')) || 1;
  const [currentLevel, setCurrentLevel] = useState(initialLevel);
  const [selectedTheme, setSelectedTheme] = useState(null);
  const copy = {
    eyebrow: isEnglish ? 'Secondary 4 Program' : 'Programme de Secondaire 4',
    title: isEnglish ? 'Historical Themes' : 'Thèmes historiques',
    intro: isEnglish
      ? 'Explore major themes in Indigenous history in Quebec and Canada, from the Indian Act to constitutional recognition.'
      : "Explorez les grands thèmes de l'histoire autochtone au Québec et au Canada, de la Loi sur les Indiens à la reconnaissance constitutionnelle.",
    translationNote: isEnglish
      ? 'This section is being translated progressively. Some detailed source content remains in French for now.'
      : null,
    depthLabel: isEnglish ? 'Learning depth:' : 'Niveau de profondeur :',
  };

  useEffect(() => {
    const level = parseInt(searchParams.get('level'));
    if (level >= 1 && level <= 3) {
      setCurrentLevel(level);
    }
  }, [searchParams]);

  return (
    <div className="min-h-screen pt-20 md:pt-24" data-testid="themes-page">
      {/* Header */}
      <section className="py-12 md:py-16 border-b border-[#E6E4DD]">
        <div className="container-full">
          <span className="overline text-[#B65F4A] mb-4 block">{copy.eyebrow}</span>
          <h1 className="mb-4">{copy.title}</h1>
          <p className="text-lg text-[#5C5856] max-w-2xl">{copy.intro}</p>
          {copy.translationNote && (
            <p className="mt-4 max-w-2xl text-sm text-[#5C5856] bg-[#FAFAF7] border border-[#E6E4DD] rounded-sm p-4">
              {copy.translationNote}
            </p>
          )}
        </div>
      </section>

      {/* Level Toggle */}
      <section className="py-6 border-b border-[#E6E4DD] bg-white sticky top-16 md:top-20 z-40">
        <div className="container-full">
          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
            <p className="text-sm text-[#5C5856]">{copy.depthLabel}</p>
            <LevelToggle currentLevel={currentLevel} onLevelChange={setCurrentLevel} locale={isEnglish ? 'en' : 'fr'} />
          </div>
        </div>
      </section>

      {/* Themes Grid or Detail */}
      <section className="section-spacing">
        <div className="container-full">
          <AnimatePresence mode="wait">
            {!selectedTheme ? (
              <motion.div
                key="grid"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
              >
                <ThemesGrid 
                  themes={historicalThemes} 
                  currentLevel={currentLevel}
                  onSelectTheme={setSelectedTheme}
                  isEnglish={isEnglish}
                />
              </motion.div>
            ) : (
              <motion.div
                key="detail"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
              >
                <ThemeDetail 
                  theme={selectedTheme} 
                  currentLevel={currentLevel}
                  onBack={() => setSelectedTheme(null)}
                  isEnglish={isEnglish}
                />
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </section>
    </div>
  );
};

const ThemesGrid = ({ themes, currentLevel, onSelectTheme, isEnglish }) => (
  <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6" data-testid="themes-grid">
    {themes.map((theme, index) => {
      const Icon = iconMap[theme.icon] || FileText;
      return (
        <motion.div
          key={theme.id}
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.4, delay: index * 0.1 }}
        >
          <button
            onClick={() => onSelectTheme(theme)}
            className="block w-full text-left theme-card group"
            data-testid={`theme-card-${theme.id}`}
          >
            <div className="theme-card-icon">
              <Icon className="w-6 h-6" />
            </div>
            <LevelBadge level={currentLevel} className="mb-3" locale={isEnglish ? 'en' : 'fr'} />
            <h3 className="text-xl mb-2 group-hover:text-[#B65F4A] transition-colors">
              {theme.title}
            </h3>
            <p className="text-sm text-[#5C5856] mb-4">{theme.subtitle}</p>
            <p className="text-sm text-[#5C5856] line-clamp-3">
              {currentLevel === 1 && theme.level1.summary}
              {currentLevel === 2 && theme.level2.context}
              {currentLevel === 3 && theme.level3.analysis.substring(0, 150) + '...'}
            </p>
            <span className="inline-flex items-center text-sm font-semibold text-[#B65F4A] mt-4 group-hover:gap-2 transition-all">
              {isEnglish ? 'Read more' : 'Lire plus'}
              <ChevronRight className="w-4 h-4 ml-1" />
            </span>
          </button>
        </motion.div>
      );
    })}
  </div>
);

const ThemeDetail = ({ theme, currentLevel, onBack, isEnglish }) => {
  const Icon = iconMap[theme.icon] || FileText;

  return (
    <div data-testid={`theme-detail-${theme.id}`}>
      <button
        onClick={onBack}
        className="flex items-center gap-2 text-[#5C5856] hover:text-[#B65F4A] mb-8 transition-colors"
        data-testid="back-to-themes"
      >
        <ArrowRight className="w-4 h-4 rotate-180" />
        {isEnglish ? 'Back to themes' : 'Retour aux thèmes'}
      </button>

      <div className="max-w-3xl">
        <div className="flex items-center gap-4 mb-6">
          <div className="theme-card-icon">
            <Icon className="w-6 h-6" />
          </div>
          <div>
            <LevelBadge level={currentLevel} className="mb-2" locale={isEnglish ? 'en' : 'fr'} />
            <h1 className="text-3xl">{theme.title}</h1>
            <p className="text-[#5C5856]">{theme.subtitle}</p>
          </div>
        </div>

        <AnimatePresence mode="wait">
          {currentLevel === 1 && (
            <LevelContent key="l1" level={1}>
              <ThemeLevel1 theme={theme} isEnglish={isEnglish} />
            </LevelContent>
          )}
          {currentLevel === 2 && (
            <LevelContent key="l2" level={2}>
              <ThemeLevel2 theme={theme} isEnglish={isEnglish} />
            </LevelContent>
          )}
          {currentLevel === 3 && (
            <LevelContent key="l3" level={3}>
              <ThemeLevel3 theme={theme} isEnglish={isEnglish} />
            </LevelContent>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
};

const ThemeLevel1 = ({ theme, isEnglish }) => (
  <div className="space-y-8">
    <Callout type="remember" locale={isEnglish ? 'en' : 'fr'}>
      <p>{theme.level1.toRemember}</p>
    </Callout>

    <div>
      <h2 className="text-xl mb-4">{isEnglish ? 'Summary' : 'Résumé'}</h2>
      <p className="text-[#5C5856] leading-relaxed">{theme.level1.summary}</p>
    </div>

    <div>
      <h2 className="text-xl mb-4">{isEnglish ? 'Key Dates' : 'Dates clés'}</h2>
      <div className="space-y-2">
        {theme.level1.keyDates.map((date, idx) => (
          <div key={idx} className="flex gap-4 p-3 bg-white border border-[#E6E4DD]">
            <span className="text-[#5C5856]">{date}</span>
          </div>
        ))}
      </div>
    </div>

    <div>
      <h2 className="text-xl mb-4">{isEnglish ? 'Key Terms' : 'Termes importants'}</h2>
      <div className="flex flex-wrap gap-2">
        {theme.level1.keyTerms.map((term, idx) => (
          <span key={idx} className="px-3 py-1 bg-[#E6E4DD] text-sm text-[#2D2926] rounded-sm">
            {term}
          </span>
        ))}
      </div>
    </div>
  </div>
);

const ThemeLevel2 = ({ theme, isEnglish }) => (
  <div className="space-y-8">
    <div>
      <h2 className="text-xl mb-4">{isEnglish ? 'Historical Context' : 'Contexte historique'}</h2>
      <p className="text-[#5C5856] leading-relaxed">{theme.level2.context}</p>
    </div>

    <Callout type="context" locale={isEnglish ? 'en' : 'fr'}>
      <p><strong>{isEnglish ? 'Causes:' : 'Causes :'}</strong> {theme.level2.causes}</p>
    </Callout>

    <div>
      <h2 className="text-xl mb-4">{isEnglish ? 'Consequences' : 'Conséquences'}</h2>
      <ul className="space-y-3">
        {theme.level2.consequences.map((cons, idx) => (
          <li key={idx} className="flex items-start gap-3">
            <ChevronRight className="w-5 h-5 text-[#D49A36] flex-shrink-0 mt-0.5" />
            <span className="text-[#5C5856]">{cons}</span>
          </li>
        ))}
      </ul>
    </div>

    <div className="p-6 bg-[#D49A36]/5 border border-[#D49A36]/20">
      <h3 className="font-semibold text-[#2D2926] mb-2">{isEnglish ? 'Connection to Max Gros-Louis' : 'Lien avec Max Gros-Louis'}</h3>
      <p className="text-sm text-[#5C5856]">{theme.level2.links}</p>
    </div>
  </div>
);

const ThemeLevel3 = ({ theme, isEnglish }) => (
  <div className="space-y-8">
    <div>
      <h2 className="text-xl mb-4">{isEnglish ? 'Deep Analysis' : 'Analyse approfondie'}</h2>
      <p className="text-[#5C5856] leading-relaxed">{theme.level3.analysis}</p>
    </div>

    <Callout type="explore" locale={isEnglish ? 'en' : 'fr'}>
      <p><strong>{isEnglish ? 'Historical debates:' : 'Débats historiographiques :'}</strong> {theme.level3.debates}</p>
    </Callout>

    <div>
      <h2 className="text-xl mb-4">{isEnglish ? 'Key Figures' : 'Personnalités clés'}</h2>
      <div className="grid gap-4">
        {theme.level3.personalities.map((person, idx) => (
          <div key={idx} className="p-4 bg-white border border-[#E6E4DD]">
            <h4 className="font-semibold text-[#2D2926]">{person.name}</h4>
            <p className="text-sm text-[#5C5856] mt-1">{person.role}</p>
          </div>
        ))}
      </div>
    </div>

    <div>
      <h2 className="text-xl mb-4">{isEnglish ? 'Documents and Sources' : 'Documents et sources'}</h2>
      <p className="text-[#5C5856] text-sm leading-relaxed">{theme.level3.documents}</p>
    </div>
  </div>
);

export default ThemesPage;
