function upsertMeta(selector, attributes) {
  let element = document.head.querySelector(selector);

  if (!element) {
    element = document.createElement("meta");
    document.head.appendChild(element);
  }

  Object.entries(attributes).forEach(([key, value]) => {
    element.setAttribute(key, value);
  });
}

function upsertLink(selector, attributes) {
  let element = document.head.querySelector(selector);

  if (!element) {
    element = document.createElement("link");
    document.head.appendChild(element);
  }

  Object.entries(attributes).forEach(([key, value]) => {
    element.setAttribute(key, value);
  });
}

function upsertAlternate(hreflang, href) {
  upsertLink(`link[rel="alternate"][hreflang="${hreflang}"]`, {
    rel: "alternate",
    hreflang,
    href,
  });
}

function getAlternatePath(pathname) {
  const map = {
    "/": "/en",
    "/enseignants": "/en/teachers",
    "/max-gros-louis": "/en/max-gros-louis",
    "/themes": "/en/themes",
    "/chronologie": "/en/timeline",
    "/quiz": "/en/quiz",
    "/glossaire": "/en/glossary",
    "/activites": "/en/activities",
    "/en": "/",
    "/en/teachers": "/enseignants",
    "/en/max-gros-louis": "/max-gros-louis",
    "/en/themes": "/themes",
    "/en/timeline": "/chronologie",
    "/en/quiz": "/quiz",
    "/en/glossary": "/glossaire",
    "/en/activities": "/activites",
  };

  return map[pathname] || "/";
}

function upsertJsonLd(id, data) {
  let element = document.head.querySelector(`script[data-seo-jsonld="${id}"]`);

  if (!element) {
    element = document.createElement("script");
    element.type = "application/ld+json";
    element.setAttribute("data-seo-jsonld", id);
    document.head.appendChild(element);
  }

  element.textContent = JSON.stringify(data);
}

function buildBreadcrumbList(pathname, labels) {
  const frenchPaths = {
    Accueil: "/",
    Enseignants: "/enseignants",
    "Max Gros-Louis": "/max-gros-louis",
    "Thèmes historiques": "/themes",
    Chronologie: "/chronologie",
    Quiz: "/quiz",
    Glossaire: "/glossaire",
    Activités: "/activites",
  };

  const englishPaths = {
    Home: "/en",
    Teachers: "/en/teachers",
    "Max Gros-Louis": "/en/max-gros-louis",
    "Historical Themes": "/en/themes",
    Timeline: "/en/timeline",
    Quiz: "/en/quiz",
    Glossary: "/en/glossary",
    Activities: "/en/activities",
  };

  const pathMap = pathname.startsWith("/en") ? englishPaths : frenchPaths;

  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: labels.map((label, index) => ({
      "@type": "ListItem",
      position: index + 1,
      name: label,
      item: `${SITE_URL}${pathMap[label] || pathname}`,
    })),
  };
}

export function SeoManager() {
  const location = useLocation();
  const seo = seoByPath[location.pathname] || seoByPath["/"];
  const canonicalUrl = `${SITE_URL}${location.pathname}`;
  const alternatePath = getAlternatePath(location.pathname);
  const alternateUrl = `${SITE_URL}${alternatePath}`;

  useEffect(() => {
    document.documentElement.lang = seo.lang;
    document.title = seo.title;

    upsertMeta('meta[name="description"]', {
      name: "description",
      content: seo.description,
    });
    upsertMeta('meta[name="robots"]', {
      name: "robots",
      content: IS_PREVIEW ? "noindex,nofollow,noarchive,nosnippet,noimageindex" : "index,follow,max-image-preview:large",
    });
    upsertMeta('meta[property="og:type"]', {
      property: "og:type",
      content: "website",
    });
    upsertMeta('meta[property="og:site_name"]', {
      property: "og:site_name",
      content: SITE_NAME,
    });
    upsertMeta('meta[property="og:locale"]', {
      property: "og:locale",
      content: seo.lang === "fr" ? "fr_CA" : "en_CA",
    });
    upsertMeta('meta[property="og:locale:alternate"]', {
      property: "og:locale:alternate",
      content: seo.lang === "fr" ? "en_CA" : "fr_CA",
    });
    upsertMeta('meta[property="og:title"]', {
      property: "og:title",
      content: seo.title,
    });
    upsertMeta('meta[property="og:description"]', {
      property: "og:description",
      content: seo.description,
    });
    upsertMeta('meta[property="og:url"]', {
      property: "og:url",
      content: canonicalUrl,
    });
    upsertMeta('meta[property="og:image"]', {
      property: "og:image",
      content: DEFAULT_IMAGE,
    });
    upsertMeta('meta[property="og:image:alt"]', {
      property: "og:image:alt",
      content: "Portrait of Grand Chief Max Gros-Louis",
    });
    upsertMeta('meta[name="twitter:card"]', {
      name: "twitter:card",
      content: "summary_large_image",
    });
    upsertMeta('meta[name="twitter:title"]', {
      name: "twitter:title",
      content: seo.title,
    });
    upsertMeta('meta[name="twitter:description"]', {
      name: "twitter:description",
      content: seo.description,
    });
    upsertMeta('meta[name="twitter:image"]', {
      name: "twitter:image",
      content: DEFAULT_IMAGE,
    });

    upsertLink('link[rel="canonical"]', {
      rel: "canonical",
      href: canonicalUrl,
    });
    upsertAlternate("x-default", `${SITE_URL}/`);
    upsertAlternate("fr-CA", seo.lang === "fr" ? canonicalUrl : alternateUrl);
    upsertAlternate("en-CA", seo.lang === "en" ? canonicalUrl : alternateUrl);

    upsertJsonLd("organization", {
      "@context": "https://schema.org",
      "@type": "Organization",
      name: SITE_NAME,
      url: SITE_URL,
      logo: ORGANIZATION_LOGO,
      sameAs: ["https://maxgroslouis.com/"],
    });

    upsertJsonLd("website", {
      "@context": "https://schema.org",
      "@type": "WebSite",
      name: SITE_NAME,
      url: SITE_URL,
      inLanguage: ["fr-CA", "en-CA"],
    });

    upsertJsonLd("webpage", {
      "@context": "https://schema.org",
      "@type": seo.pageType || "WebPage",
      name: seo.title,
      description: seo.description,
      url: canonicalUrl,
      isPartOf: {
        "@type": "WebSite",
        name: SITE_NAME,
        url: SITE_URL,
      },
      about: [
        "Indigenous history in Quebec",
        "Max Gros-Louis",
        "Secondary education",
      ],
      inLanguage: seo.lang === "fr" ? "fr-CA" : "en-CA",
      primaryImageOfPage: DEFAULT_IMAGE,
    });

    upsertJsonLd("breadcrumbs", buildBreadcrumbList(location.pathname, seo.breadcrumb || [seo.lang === "fr" ? "Accueil" : "Home"]));
  }, [canonicalUrl, alternateUrl, location.pathname, seo]);

  return null;
}
