import { motion } from 'framer-motion';

const levelSets = {
  fr: [
    { id: 1, label: 'Résumé rapide', shortLabel: 'Niveau 1', badgeLabel: 'Niveau 1', color: 'level-1' },
    { id: 2, label: 'Comprendre', shortLabel: 'Niveau 2', badgeLabel: 'Niveau 2', color: 'level-2' },
    { id: 3, label: 'Analyse approfondie', shortLabel: 'Niveau 3', badgeLabel: 'Niveau 3', color: 'level-3' },
  ],
  en: [
    { id: 1, label: 'Quick Review', shortLabel: 'Level 1', badgeLabel: 'Level 1', color: 'level-1' },
    { id: 2, label: 'Understand', shortLabel: 'Level 2', badgeLabel: 'Level 2', color: 'level-2' },
    { id: 3, label: 'Deep Analysis', shortLabel: 'Level 3', badgeLabel: 'Level 3', color: 'level-3' },
  ],
};

export const LevelToggle = ({ currentLevel, onLevelChange, className = '', locale = 'fr' }) => {
  const levels = levelSets[locale] || levelSets.fr;

  return (
    <div 
      className={`flex flex-wrap gap-2 ${className}`}
      role="tablist"
      aria-label={locale === 'en' ? 'Learning depth levels' : 'Niveaux de profondeur'}
      data-testid="level-toggle"
    >
      {levels.map((level) => (
        <button
          key={level.id}
          onClick={() => onLevelChange(level.id)}
          className={`level-pill level-pill-${level.id} ${
            currentLevel === level.id ? 'active' : ''
          }`}
          role="tab"
          aria-selected={currentLevel === level.id}
          aria-label={`${level.label} - ${level.shortLabel}`}
          data-testid={`level-toggle-${level.id}`}
        >
          <span className="hidden sm:inline">{level.label}</span>
          <span className="sm:hidden">{level.shortLabel}</span>
        </button>
      ))}
    </div>
  );
};

export const LevelBadge = ({ level, className = '', locale = 'fr' }) => {
  const levels = levelSets[locale] || levelSets.fr;
  const levelInfo = levels.find(l => l.id === level) || levels[0];
  
  return (
    <span 
      className={`inline-flex items-center px-2 py-0.5 text-xs font-semibold rounded-sm bg-level-${level} text-white ${className}`}
      data-testid={`level-badge-${level}`}
    >
      {levelInfo.badgeLabel}
    </span>
  );
};

export const LevelContent = ({ level, children, className = '' }) => {
  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, y: -10 }}
      transition={{ duration: 0.3 }}
      className={className}
      data-testid={`level-content-${level}`}
    >
      {children}
    </motion.div>
  );
};
