import { useState } from 'react';
import { useLocation } from 'react-router-dom';
import { motion } from 'framer-motion';
import { 
  PenTool, Users, GitCompare, Clock, MessageSquare, 
  Search, Target, ChevronRight, Filter
} from 'lucide-react';
import { studentActivities } from '../data/content';
import { Button } from '../components/ui/button';

const iconMap = {
  'fill-blank': PenTool,
  'matching': Users,
  'reflection': MessageSquare,
  'comparison': GitCompare,
  'ordering': Clock,
  'museum-hunt': Search,
  'research': Search,
  'debate': MessageSquare,
};

const ActivitiesPage = () => {
  const location = useLocation();
  const isEnglish = location.pathname.startsWith('/en');
  const [selectedDifficulty, setSelectedDifficulty] = useState('all');
  const [expandedActivity, setExpandedActivity] = useState(null);
  const difficultyLabels = {
    all: isEnglish ? 'All' : 'Tous',
    facile: isEnglish ? 'Easy' : 'Facile',
    intermédiaire: isEnglish ? 'Intermediate' : 'Intermédiaire',
    avancé: isEnglish ? 'Advanced' : 'Avancé',
  };

  const filteredActivities = selectedDifficulty === 'all' 
    ? studentActivities 
    : studentActivities.filter(a => a.difficulty === selectedDifficulty);

  return (
    <div className="min-h-screen pt-20 md:pt-24" data-testid="activities-page">
      {/* Header */}
      <section className="py-12 md:py-16 border-b border-[#E6E4DD]">
        <div className="container-full">
          <span className="overline text-[#B65F4A] mb-4 block">{isEnglish ? 'Active Learning' : 'Apprentissage actif'}</span>
          <h1 className="mb-4">{isEnglish ? 'Student Activities' : 'Activités pour élèves'}</h1>
          <p className="text-lg text-[#5C5856] max-w-2xl">
            {isEnglish
              ? 'Interactive exercises, reflection prompts, and research activities to deepen understanding of Indigenous history.'
              : "Exercices interactifs, réflexions et activités de recherche pour approfondir votre compréhension de l'histoire autochtone."}
          </p>
          {isEnglish && (
            <p className="mt-4 max-w-2xl text-sm text-[#5C5856] bg-[#FAFAF7] border border-[#E6E4DD] rounded-sm p-4">
              This activity section now has an English interface. Detailed activity content is still being translated progressively.
            </p>
          )}
        </div>
      </section>

      {/* Filters */}
      <section className="py-6 border-b border-[#E6E4DD] bg-white sticky top-16 md:top-20 z-40">
        <div className="container-full">
          <div className="flex items-center gap-4">
            <Filter className="w-5 h-5 text-[#5C5856]" />
            <span className="text-sm text-[#5C5856]">{isEnglish ? 'Difficulty:' : 'Difficulté :'}</span>
            <div className="flex gap-2 flex-wrap">
              {['all', 'facile', 'intermédiaire', 'avancé'].map((diff) => (
                <button
                  key={diff}
                  onClick={() => setSelectedDifficulty(diff)}
                  className={`filter-btn ${selectedDifficulty === diff ? 'active' : ''}`}
                  data-testid={`activity-filter-${diff}`}
                >
                  {difficultyLabels[diff]}
                </button>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* Activities Grid */}
      <section className="section-spacing">
        <div className="container-full">
          <div className="grid md:grid-cols-2 gap-6">
            {filteredActivities.map((activity, index) => {
              const Icon = iconMap[activity.type] || Target;
              const isExpanded = expandedActivity === activity.id;

              return (
                <motion.div
                  key={activity.id}
                  initial={{ opacity: 0, y: 20 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.4, delay: index * 0.1 }}
                  data-testid={`activity-card-${activity.id}`}
                >
                  <div className="activity-card h-full flex flex-col">
                    <div className="activity-card-header flex items-start justify-between gap-4">
                      <div className="flex items-start gap-4">
                        <div className="w-10 h-10 rounded-sm bg-[#B65F4A]/10 flex items-center justify-center flex-shrink-0">
                          <Icon className="w-5 h-5 text-[#B65F4A]" />
                        </div>
                        <div>
                          <h3 className="text-lg font-semibold text-[#2D2926] mb-1">
                            {activity.title}
                          </h3>
                          <span className={`activity-difficulty difficulty-${activity.difficulty}`}>
                            {activity.difficulty}
                          </span>
                        </div>
                      </div>
                    </div>

                    <div className="activity-card-body flex-1 flex flex-col">
                      <p className="text-sm text-[#5C5856] mb-4">
                        {activity.instructions}
                      </p>

                      {isExpanded && (
                        <motion.div
                          initial={{ opacity: 0 }}
                          animate={{ opacity: 1 }}
                          className="mt-4 pt-4 border-t border-[#E6E4DD]"
                        >
                          <ActivityContent activity={activity} isEnglish={isEnglish} />
                        </motion.div>
                      )}

                      <div className="mt-auto pt-4">
                        <Button
                          variant="outline"
                          onClick={() => setExpandedActivity(isExpanded ? null : activity.id)}
                          className="w-full justify-center border-[#E6E4DD] rounded-sm"
                          data-testid={`activity-toggle-${activity.id}`}
                        >
                          {isExpanded ? (isEnglish ? 'Collapse' : 'Réduire') : (isEnglish ? 'View activity' : "Voir l'activité")}
                          <ChevronRight className={`w-4 h-4 ml-2 transition-transform ${isExpanded ? 'rotate-90' : ''}`} />
                        </Button>
                      </div>
                    </div>
                  </div>
                </motion.div>
              );
            })}
          </div>
        </div>
      </section>
    </div>
  );
};

const ActivityContent = ({ activity, isEnglish }) => {
  switch (activity.type) {
    case 'fill-blank':
      return (
        <div className="space-y-3">
          {activity.items.map((item, idx) => (
            <div key={idx} className="p-3 bg-[#FAFAF7] border border-[#E6E4DD] rounded-sm">
              <p className="text-sm text-[#2D2926]">{item.text}</p>
              <p className="text-xs text-[#4B6858] mt-1">{isEnglish ? 'Answer:' : 'Réponse :'} {item.answer}</p>
            </div>
          ))}
        </div>
      );

    case 'matching':
      return (
        <div className="space-y-2">
          {activity.pairs.map((pair, idx) => (
            <div key={idx} className="flex items-center gap-4 p-3 bg-[#FAFAF7] border border-[#E6E4DD] rounded-sm">
              <span className="font-semibold text-sm">{pair.person}</span>
              <ChevronRight className="w-4 h-4 text-[#B65F4A]" />
              <span className="text-sm text-[#5C5856]">{pair.event}</span>
            </div>
          ))}
        </div>
      );

    case 'reflection':
      return (
        <div className="space-y-3">
          <p className="text-sm text-[#5C5856] italic">{isEnglish ? 'Reflection prompts:' : 'Pistes de réflexion :'}</p>
          {activity.prompts.map((prompt, idx) => (
            <div key={idx} className="flex items-start gap-2">
              <span className="text-[#B65F4A]">•</span>
              <p className="text-sm text-[#5C5856]">{prompt}</p>
            </div>
          ))}
        </div>
      );

    case 'comparison':
      return (
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-[#E6E4DD]">
                <th className="p-2 text-left text-[#5C5856]">{isEnglish ? 'Criteria' : 'Critère'}</th>
                {activity.items.map((item, idx) => (
                  <th key={idx} className="p-2 text-left font-semibold">{item.name}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {activity.categories.map((cat, idx) => (
                <tr key={idx} className="border-b border-[#E6E4DD]">
                  <td className="p-2 text-[#5C5856]">{cat}</td>
                  {activity.items.map((item, itemIdx) => (
                    <td key={itemIdx} className="p-2 text-[#4B6858]">{item.hints[idx]}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );

    case 'ordering':
      return (
        <div className="space-y-2">
          <p className="text-sm text-[#5C5856] mb-3">{isEnglish ? 'Correct chronological order:' : 'Ordre chronologique correct :'}</p>
          {[...activity.items].sort((a, b) => a.year - b.year).map((item, idx) => (
            <div key={idx} className="flex items-center gap-4 p-3 bg-[#FAFAF7] border border-[#E6E4DD] rounded-sm">
              <span className="w-6 h-6 rounded-full bg-[#4B6858] text-white text-xs flex items-center justify-center">
                {idx + 1}
              </span>
              <span className="font-semibold text-sm">{item.year}</span>
              <span className="text-sm text-[#5C5856]">{item.event}</span>
            </div>
          ))}
        </div>
      );

    case 'museum-hunt':
    case 'research':
      return (
        <div className="space-y-3">
          {activity.questions.map((question, idx) => (
            <div key={idx} className="flex items-start gap-3 p-3 bg-[#FAFAF7] border border-[#E6E4DD] rounded-sm">
              <span className="w-6 h-6 rounded-full bg-[#D49A36] text-white text-xs flex items-center justify-center flex-shrink-0">
                {idx + 1}
              </span>
              <p className="text-sm text-[#2D2926]">{question}</p>
            </div>
          ))}
        </div>
      );

    case 'debate':
      return (
        <div className="space-y-4">
          {activity.positions.map((position, idx) => (
            <div key={idx} className="p-4 bg-[#FAFAF7] border border-[#E6E4DD] rounded-sm">
              <h4 className="font-semibold text-[#2D2926] mb-2">{position.side}</h4>
              <ul className="space-y-1">
                {position.arguments.map((arg, argIdx) => (
                  <li key={argIdx} className="flex items-start gap-2 text-sm text-[#5C5856]">
                    <span className="text-[#B65F4A]">•</span>
                    {arg}
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      );

    default:
      return null;
  }
};

export default ActivitiesPage;
