import { useState, useMemo } from 'react';
import { useLocation } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { Calendar, Filter, X, ChevronDown, ChevronUp } from 'lucide-react';
import { timelineEvents, timelineFilters } from '../data/content';
import { LevelToggle } from '../components/shared/LevelToggle';

const TimelinePage = () => {
  const location = useLocation();
  const isEnglish = location.pathname.startsWith('/en');
  const [currentLevel, setCurrentLevel] = useState(1);
  const [activeFilter, setActiveFilter] = useState('all');
  const [expandedEvent, setExpandedEvent] = useState(null);
  const filterLabelsEn = {
    all: 'All',
    droits: 'Rights',
    politique: 'Politics',
    'revendications-territoriales': 'Land Claims',
    'max-gros-louis': 'Max Gros-Louis',
  };

  const filteredEvents = useMemo(() => {
    if (activeFilter === 'all') return timelineEvents;
    return timelineEvents.filter(event => event.category === activeFilter);
  }, [activeFilter]);

  const sortedEvents = useMemo(() => {
    return [...filteredEvents].sort((a, b) => a.year - b.year);
  }, [filteredEvents]);

  return (
    <div className="min-h-screen pt-20 md:pt-24" data-testid="timeline-page">
      {/* Header */}
      <section className="py-12 md:py-16 border-b border-[#E6E4DD]">
        <div className="container-full">
          <span className="overline text-[#B65F4A] mb-4 block">{isEnglish ? 'Historical Reference Points' : 'Repères historiques'}</span>
          <h1 className="mb-4">{isEnglish ? 'Interactive Timeline' : 'Chronologie interactive'}</h1>
          <p className="text-lg text-[#5C5856] max-w-2xl">
            {isEnglish
              ? 'Explore major events in modern Indigenous history, from the Indian Act to the present day.'
              : "Explorez les événements majeurs de l'histoire autochtone moderne, de la Loi sur les Indiens à nos jours."}
          </p>
          {isEnglish && (
            <p className="mt-4 max-w-2xl text-sm text-[#5C5856] bg-[#FAFAF7] border border-[#E6E4DD] rounded-sm p-4">
              This timeline interface is available in English. Detailed event text is still being translated progressively.
            </p>
          )}
        </div>
      </section>

      {/* Controls */}
      <section className="py-6 border-b border-[#E6E4DD] bg-white sticky top-16 md:top-20 z-40">
        <div className="container-full">
          <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
            {/* Filters */}
            <div className="flex flex-wrap gap-2" data-testid="timeline-filters">
              {timelineFilters.map((filter) => (
                <button
                  key={filter.id}
                  onClick={() => setActiveFilter(filter.id)}
                  className={`filter-btn ${activeFilter === filter.id ? 'active' : ''}`}
                  style={activeFilter === filter.id ? { backgroundColor: filter.color, borderColor: filter.color } : {}}
                  data-testid={`filter-${filter.id}`}
                >
                  {isEnglish ? (filterLabelsEn[filter.id] || filter.label) : filter.label}
                </button>
              ))}
            </div>

            {/* Level Toggle */}
            <LevelToggle currentLevel={currentLevel} onLevelChange={setCurrentLevel} locale={isEnglish ? 'en' : 'fr'} />
          </div>
        </div>
      </section>

      {/* Timeline */}
      <section className="section-spacing">
        <div className="container-narrow">
          <div className="relative">
            {/* Vertical line */}
            <div className="absolute left-4 md:left-1/2 md:-translate-x-px top-0 bottom-0 w-0.5 bg-[#E6E4DD]" />

            {/* Events */}
            <div className="space-y-8 md:space-y-12">
              {sortedEvents.map((event, index) => (
                <TimelineEvent
                  key={event.id}
                  event={event}
                  index={index}
                  currentLevel={currentLevel}
                  isEnglish={isEnglish}
                  isExpanded={expandedEvent === event.id}
                  onToggle={() => setExpandedEvent(expandedEvent === event.id ? null : event.id)}
                />
              ))}
            </div>
          </div>

          {filteredEvents.length === 0 && (
            <div className="text-center py-12">
              <p className="text-[#5C5856]">{isEnglish ? 'No events found for this filter.' : 'Aucun événement trouvé pour ce filtre.'}</p>
              <button
                onClick={() => setActiveFilter('all')}
                className="mt-4 text-[#B65F4A] font-semibold hover:underline"
              >
                {isEnglish ? 'Show all events' : 'Afficher tous les événements'}
              </button>
            </div>
          )}
        </div>
      </section>
    </div>
  );
};

const TimelineEvent = ({ event, index, currentLevel, isExpanded, onToggle, isEnglish }) => {
  const isEven = index % 2 === 0;
  const filterColor = timelineFilters.find(f => f.id === event.category)?.color || '#2D2926';

  const getContent = () => {
    switch (currentLevel) {
      case 1: return event.level1;
      case 2: return event.level2;
      case 3: return event.level3;
      default: return event.level1;
    }
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.4, delay: index * 0.05 }}
      className={`relative flex items-start gap-4 md:gap-8 ${isEven ? 'md:flex-row' : 'md:flex-row-reverse'}`}
      data-testid={`timeline-event-${event.id}`}
    >
      {/* Timeline dot */}
      <div className="absolute left-4 md:left-1/2 md:-translate-x-1/2 z-10">
        <div 
          className="w-4 h-4 rounded-full border-4 border-[#FAFAF7]"
          style={{ backgroundColor: filterColor }}
        />
      </div>

      {/* Date badge (mobile) */}
      <div className="md:hidden pl-10 w-full">
        <span 
          className="inline-block px-3 py-1 text-sm font-semibold text-white rounded-sm mb-2"
          style={{ backgroundColor: filterColor }}
        >
          {event.year}
        </span>
      </div>

      {/* Content */}
      <div className={`w-full md:w-[calc(50%-2rem)] ${isEven ? 'md:pr-8' : 'md:pl-8'} pl-10 md:pl-0`}>
        {/* Date badge (desktop) */}
        <span 
          className="hidden md:inline-block px-3 py-1 text-sm font-semibold text-white rounded-sm mb-3"
          style={{ backgroundColor: filterColor }}
        >
          {event.year}
        </span>

        <div className="card-museum p-6">
          <h3 className="text-lg font-semibold text-[#2D2926] mb-2">{event.title}</h3>
          <p className="text-sm text-[#5C5856] mb-4">{event.description}</p>

          <button
            onClick={onToggle}
            className="flex items-center gap-2 text-sm font-semibold text-[#B65F4A] hover:underline"
            data-testid={`timeline-expand-${event.id}`}
          >
            {isExpanded ? (isEnglish ? 'Collapse' : 'Réduire') : (isEnglish ? 'Learn more' : 'En savoir plus')}
            {isExpanded ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
          </button>

          <AnimatePresence>
            {isExpanded && (
              <motion.div
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: 'auto', opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                transition={{ duration: 0.3 }}
                className="overflow-hidden"
              >
                <div className="pt-4 mt-4 border-t border-[#E6E4DD]">
                  <div className="flex items-center gap-2 mb-2">
                    <span 
                      className="text-xs font-semibold uppercase tracking-wider"
                      style={{ color: filterColor }}
                    >
                      {isEnglish ? `Level ${currentLevel}` : `Niveau ${currentLevel}`}
                    </span>
                  </div>
                  <p className="text-sm text-[#5C5856] leading-relaxed">
                    {getContent()}
                  </p>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>

      {/* Spacer for opposite side */}
      <div className="hidden md:block w-[calc(50%-2rem)]" />
    </motion.div>
  );
};

export default TimelinePage;
